export default function Dashboard() {
  const counts = statuses.map((status) => ({
    status,
    count: issues.filter((issue) => issue.status === status).length,
  }));

  const recent = [...issues]
    .sort((a, b) => {
      const timestamp = (date: string) => {
        const [year, month, day] = date.split('-').map(Number);
