import { useSearchParams } from 'react-router-dom';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues } from '../data/issues';

export default function IssueList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const validStatuses = ['all', 'open', 'in-progress', 'resolved', 'closed'];
  const validAssignees = ['all', 'Mara', 'Deniz', 'Kofi', 'Priya', 'Tomas'];
  const requestedStatus = searchParams.get('status') ?? 'all';
  const requestedAssignee = searchParams.get('assignee') ?? 'all';
  const status = validStatuses.includes(requestedStatus) ? requestedStatus : 'all';
  const assignee = validAssignees.includes(requestedAssignee) ? requestedAssignee : 'all';

  const updateFilter = (key: 'status' | 'assignee', value: string) => {
    const next = new URLSearchParams(searchParams);
    if (value === 'all') next.delete(key);
    else next.set(key, value);
    setSearchParams(next);
  };

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <h1>Issues</h1>
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={(value) => updateFilter('status', value)}
        onAssigneeChange={(value) => updateFilter('assignee', value)}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

