import { useState, type FormEvent } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues, type Issue } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [issueList, setIssueList] = useState(issues);
  const [isCreating, setIsCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');

  const visible = issueList.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  function createIssue(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const cleanTitle = title.trim();
    if (!cleanTitle) {
      setTitleError('Title is required.');
      return;
    }

    const newIssue: Issue = {
      id: Math.max(...issueList.map((issue) => issue.id), 0) + 1,
      title: cleanTitle,
      description: '',
      status: 'open',
      assignee: 'Mara',
      tags: [],
      createdAt: new Date().toISOString().slice(0, 10),
    };
    setIssueList((current) => [newIssue, ...current]);
    setTitle('');
    setTitleError('');
    setIsCreating(false);
    setStatus('all');
    setAssignee('all');
  }

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => { setIsCreating(true); setTitleError(''); }}>New issue</button>
      </div>
      {isCreating && (
        <form className="new-issue-form" onSubmit={createIssue}>
          <label htmlFor="new-issue-title">Title</label>
          <input
            id="new-issue-title"
            autoFocus
            value={title}
            onChange={(event) => { setTitle(event.target.value); setTitleError(''); }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'new-issue-title-error' : undefined}
          />
          {titleError && <p id="new-issue-title-error" className="form-error" role="alert">{titleError}</p>}
          <div className="new-issue-actions">
            <button type="submit">Create issue</button>
            <button type="button" onClick={() => { setIsCreating(false); setTitle(''); setTitleError(''); }}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issueList.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

