import { useState, type FormEvent } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [showForm, setShowForm] = useState(false);
  const [title, setTitle] = useState('');
  const [error, setError] = useState('');
  const [createdIssues, setCreatedIssues] = useState<typeof issues>([]);
  const allIssues = [...createdIssues, ...issues];

  const visible = allIssues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  function createIssue(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const cleanTitle = title.trim();
    if (!cleanTitle) {
      setError('Title is required.');
      return;
    }
    setCreatedIssues((current) => [{
      id: Math.max(...allIssues.map((issue) => issue.id), 0) + 1,
      title: cleanTitle,
      description: '',
      status: 'open',
      assignee: '',
      tags: [],
      createdAt: new Date().toISOString().slice(0, 10),
    }, ...current]);
    setTitle('');
    setError('');
    setShowForm(false);
  }

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => { setShowForm((open) => !open); setError(''); }}>New issue</button>
      </div>
      {showForm && (
        <form className="new-issue-form" onSubmit={createIssue}>
          <label htmlFor="new-issue-title">Title</label>
          <input id="new-issue-title" autoFocus value={title} onChange={(event) => { setTitle(event.target.value); setError(''); }} />
          {error && <p className="form-error" role="alert">{error}</p>}
          <div className="new-issue-form__actions">
            <button type="submit">Create issue</button>
            <button type="button" onClick={() => { setShowForm(false); setError(''); }}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {allIssues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

