import { useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues as initialIssues, type Issue } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [issues, setIssues] = useState<Issue[]>(initialIssues);
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState(false);

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => { setCreating(true); setTitleError(false); }}>New issue</button>
      </div>
      {creating && (
        <form className="new-issue-form" onSubmit={(event) => {
          event.preventDefault();
          const cleanTitle = title.trim();
          if (!cleanTitle) { setTitleError(true); return; }
          const issue: Issue = {
            id: Math.max(0, ...issues.map((item) => item.id)) + 1,
            title: cleanTitle,
            description: '',
            status: 'open',
            assignee: 'Unassigned',
            tags: [],
            createdAt: new Date().toISOString().slice(0, 10),
          };
          setIssues((current) => [issue, ...current]);
          setTitle('');
          setTitleError(false);
          setCreating(false);
        }}>
          <label htmlFor="new-issue-title">Title</label>
          <input id="new-issue-title" value={title} onChange={(event) => { setTitle(event.target.value); setTitleError(false); }} aria-invalid={titleError} aria-describedby={titleError ? 'new-issue-title-error' : undefined} />
          {titleError && <p id="new-issue-title-error" className="form-error" role="alert">Title is required.</p>}
          <div className="new-issue-form__actions">
            <button type="submit">Create issue</button>
            <button type="button" onClick={() => { setCreating(false); setTitleError(false); }}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

