import { useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [showForm, setShowForm] = useState(false);
  const [title, setTitle] = useState('');
  const [error, setError] = useState('');
  const [, refreshIssues] = useState(0);

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => { setShowForm((open) => !open); setError(''); }}>
          {showForm ? 'Cancel' : 'New issue'}
        </button>
      </div>
      {showForm && (
        <form className="new-issue-form" onSubmit={(event) => {
          event.preventDefault();
          const cleanTitle = title.trim();
          if (!cleanTitle) {
            setError('Title is required.');
            return;
          }
          issues.unshift({
            id: Math.max(0, ...issues.map((issue) => issue.id)) + 1,
            title: cleanTitle,
            description: '',
            status: 'open',
            assignee: 'Unassigned',
            tags: [],
            createdAt: new Date().toISOString().slice(0, 10),
          });
          refreshIssues((count) => count + 1);
          setTitle('');
          setError('');
          setShowForm(false);
        }}>
          <label htmlFor="new-issue-title">Title</label>
          <input id="new-issue-title" value={title} onChange={(event) => { setTitle(event.target.value); setError(''); }} />
          {error && <p className="form-error" role="alert">{error}</p>}
          <button type="submit">Create issue</button>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

